#!/usr/bin/env python3
"""Supplementary LaTeX tables from the full-dataset results (generated - do not edit the .tex by hand).

    python3 full_supp_tables.py
Reads results/full/{eval,runtime,tracking}.json; writes cvpr2027_paper/tables/supp_{scenario,stats,splits,cost}.tex.
"""
import json
import os

HERE = os.path.dirname(os.path.abspath(__file__))
R = os.path.join(HERE, "results", "full")
TAB = os.path.join(HERE, "..", "..", "cvpr2027_paper", "tables")
E = json.load(open(os.path.join(R, "eval.json")))
TR = json.load(open(os.path.join(R, "tracking.json")))
HDR = "% generated by go2-engagement/engage/full_supp_tables.py - do not edit by hand\n"
NM = {"gesture_only": "Gesture only", "nearest": "Nearest person", "distance_only": "Distance only", "facing_only": "Facing only",
      "gaze_only": "Gaze only", "logreg": "Logistic regr.", "type1": "Type-1", "type1_gaze": "Type-1 + gaze",
      "type1_mono": "Type-1, no depth", "it2": "IT2", "it2_gaze": "IT2 + gaze", "it2_mono": "IT2, no depth"}


def fr(v):
    f, r = v["false_trigger"], v["recall"]
    a = "--" if f["n"] == 0 else f"{100 * f['p']:.0f}"
    return f"{a}/{100 * r['p']:.0f}"


def pv(p):
    return r"$<10^{-15}$" if p < 1e-15 else f"{p:.2g}"


def write(name, body):
    open(os.path.join(TAB, name + ".tex"), "w").write(HDR + body)


# by scenario / day / label source
ms = ["gesture_only", "facing_only", "gaze_only", "type1", "it2", "it2_gaze"]
rows = []
for g, title in (("scenario", "Scenario"), ("day", "Recording day"), ("source", "Labels")):
    rows.append(r"\midrule" + "\n" + rf"\multicolumn{{7}}{{@{{}}l}}{{\emph{{{title}}}}}\\")
    for v, row in E["by"][g].items():
        lab = {"labels.json": "episode by episode", "labels_cmd.json": "commander chosen"}.get(v, v)
        rows.append(f"{lab} & " + " & ".join(fr(row[m]) for m in ms) + r"\\")
write("supp_scenario", r"""\begin{table}[h]
\centering\small\setlength{\tabcolsep}{1.6pt}
\caption{False triggers\,/\,recall (\%) by scenario, recording day and labelling mode. S1 has no bystander
gestures (--). S5 has only 8 bystander episodes.}
\label{tab:supp_scenario}
\begin{tabular}{@{}lcccccc@{}}
\toprule
& Gesture & Facing & Gaze & Type-1 & IT2 & IT2\\
& only & only & only & & & + gaze\\
""" + "\n".join(rows) + r"""
\bottomrule
\end{tabular}
\end{table}
""")

# McNemar + bootstrap, IT2 + gaze vs every other policy
st = E["stats"]["it2_gaze"]
rows = []
for m, v in st.items():
    rows.append(f"{NM[m]} & {v['n']['only_it2_gaze']}\\,/\\,{v['n']['only_other']} & {pv(v['n']['p_holm'])} & "
                f"{v['r']['only_it2_gaze']}\\,/\\,{v['r']['only_other']} & {pv(v['r']['p_holm'])} & "
                f"${v['boot_ft_pts'][0]:+.1f}$ to ${v['boot_ft_pts'][1]:+.1f}$ & "
                f"${v['boot_recall_pts'][0]:+.1f}$ to ${v['boot_recall_pts'][1]:+.1f}$\\\\")
write("supp_stats", r"""\begin{table*}[t]
\centering\small
\caption{IT2 + gaze against every other policy on the same episodes. Discordant episodes (only IT2 + gaze
accepts\,/\,only the other accepts), exact McNemar $p$ (Holm-corrected over all NTESTS tests), and 95\,\%
bootstrap intervals (10{,}000 resamples of recordings) of the difference IT2 + gaze minus the other, in
points. Negative $\Delta$FT is better.}
\label{tab:supp_stats}
\begin{tabular}{@{}lcccccc@{}}
\toprule
& \multicolumn{2}{c}{Bystander ($n$)} & \multicolumn{2}{c}{Robot-directed ($r$)} & & \\
\cmidrule(lr){2-3}\cmidrule(lr){4-5}
vs. & only ours\,/\,other & $p$ & only ours\,/\,other & $p$ & $\Delta$FT & $\Delta$recall\\
\midrule
""".replace("NTESTS", str(2 * len(st))) + "\n".join(rows) + r"""
\bottomrule
\end{tabular}
\end{table*}
""")

# splits incl. gaze sigma and distance bins, ablations
B = E["splits"]["bins"]
rows = []
for b, bl in B.items():
    for n, v in bl.items():
        nm = {"facing σ": r"$\sigma_f$", "distance σ": r"$\sigma_d$", "gaze σ": r"$\sigma_g$",
              "distance": "distance"}[b]
        n2 = n.replace("–", "--").replace("≥", r"$\ge$").replace("<", "$<$")
        rows.append(f"{nm} {n2} & " + " & ".join(fr(v[m]) for m in ("type1", "it2", "type1_gaze", "it2_gaze",
                                                                      "facing_only")) + r"\\")
ab = E["ablations"]
abl = "\n".join(f"rules: {k} & {fr(v['type1'])} & {fr(v['it2'])} & & & \\\\" for k, v in ab.items())
write("supp_splits", r"""\begin{table}[h]
\centering\small\setlength{\tabcolsep}{1.8pt}
\caption{False triggers\,/\,recall (\%) by episode-mean uncertainty (split at the median), by distance, and
with inputs removed from the rule base.}
\label{tab:supp_splits}
\begin{tabular}{@{}lccccc@{}}
\toprule
& Type-1 & IT2 & T1 + gaze & IT2 + gaze & Facing\\
\midrule
""" + "\n".join(rows) + "\n" + r"\midrule" + "\n" + abl + r"""
\bottomrule
\end{tabular}
\end{table}
""")

# single-cue thresholds without data
U, it = E["untuned"], E["policies"]["it2_gaze"]
ths = list(U["facing_only"])
rows = [f"{t} & " + " & ".join(fr(U[m][t]) for m in ("facing_only", "gaze_only")) + r"\\" for t in ths]
write("supp_untuned", r"""\begin{table}[h]
\centering\small\setlength{\tabcolsep}{4pt}
\caption{Single-cue thresholds chosen without data, applied to all recordings: false triggers\,/\,recall
(\%). Fitted leave-one-recording-out, the thresholds are """ + f"{E['fitted_tau_median']['facing_only']:.2f}"
      + r" (facing) and " + f"{E['fitted_tau_median']['gaze_only']:.2f}" + r""" (gaze). For comparison, IT2 + gaze,
with no fitted parameter: """ + fr(it) + r""".}
\label{tab:supp_untuned}
\begin{tabular}{@{}lcc@{}}
\toprule
Threshold & Facing only & Gaze only\\
\midrule
""" + "\n".join(rows) + r"""
\bottomrule
\end{tabular}
\end{table}
""")

# results under the second annotator's labels / only agreed episodes
AG = json.load(open(os.path.join(R, "agreement.json")))
alt = {"A (paper)": E}
for name, d in (("C", "full_labels_C"), ("A and C agree", "full_labels_agree")):
    f = os.path.join(HERE, "results", d, "eval.json")
    if os.path.exists(f):
        alt[name] = json.load(open(f))
ms_ = ["gesture_only", "nearest", "facing_only", "logreg", "type1_gaze", "it2", "it2_gaze"]
hdr = " & ".join(alt) + r"\\"
rows = [f"{NM[m]} & " + " & ".join(fr(v['policies'][m]) for v in alt.values()) + r"\\" for m in ms_]
neps = " & ".join(f"{v['episodes']['r']}\\,/\\,{v['episodes']['n']}" for v in alt.values())
o = AG["overall_rn"]
write("supp_annot", rf"""\begin{{table}}[h]
\centering\small\setlength{{\tabcolsep}}{{3pt}}
\caption{{False triggers\,/\,recall (\%) with the labels of the first annotator (A, used in the paper), the
independent second annotator (C, every episode of all 60 recordings), and only the episodes on which both agree.
Agreement: {100 * o['agreement']:.1f}\%, Cohen's $\kappa={o['kappa']:.2f}$ (95\% CI {o['ci'][0]:.2f}--{o['ci'][1]:.2f}) on
{o['n']:,} episodes.}}
\label{{tab:supp_annot}}
\begin{{tabular}}{{@{{}}l{"c" * len(alt)}@{{}}}}
\toprule
Labels & {hdr}
\midrule
""".replace(f"{o['n']:,}", f"{o['n']:,}".replace(",", "{,}")) + "\n".join(rows) + r"""
\midrule
Episodes $r$\,/\,$n$ & """ + neps + r"""\\
\bottomrule
\end{tabular}
\end{table}
""")

# walking recordings: by scenario, with track fragmentation
WE = json.load(open(os.path.join(HERE, "results", "full_walking", "eval.json")))
TW = json.load(open(os.path.join(R, "tracking_walking.json")))["by_scenario"]
WN = {"W1": "leads", "W2": "pair", "W3": "crossing", "W4": "leave", "W5": "lookalike", "W6": "turn away"}
wm = ["gesture_only", "nearest", "facing_only", "type1_gaze", "it2_gaze"]
rows = [f"{sc} {WN[sc]} & " + " & ".join(fr(WE['by']['scenario'][sc][m]) if m in WE['by']['scenario'][sc]
                                          else "" for m in wm[:3] + ["type1", "it2_gaze"]) + f" & {TW[sc]['tracks_per_person']:.1f}\\\\"
        for sc in WN]
allw = "All & " + " & ".join(fr(WE["policies"][m]) for m in wm[:3] + ["type1", "it2_gaze"]) + \
       f" & {json.load(open(os.path.join(R, 'tracking_walking.json')))['total']['tracks_per_person']:.1f}\\\\"
write("supp_walking", r"""\begin{table}[h]
\centering\small\setlength{\tabcolsep}{1.6pt}
\caption{Walking recordings: false triggers\,/\,recall (\%) by scenario, and track IDs per person in view (IDs).
Fitted baselines use thresholds from the standing recordings.}
\label{tab:supp_walking}
\begin{tabular}{@{}lcccccc@{}}
\toprule
& Gesture & Nearest & Facing & Type-1 & IT2 & IDs\\
& only & person & only & & + gaze & \\
\midrule
""" + "\n".join(rows) + "\n\\midrule\n" + allw + r"""
\bottomrule
\end{tabular}
\end{table}
""")

# runtime on three devices + tracking
HW = json.load(open(os.path.join(R, "hardware", "summary.json")))
dv = HW["devices"]
cols = list(dv)
def rowv(name, f, fmt):
    return f"{name} & " + " & ".join(fmt.format(f(dv[c])) for c in cols) + r"\\"
pm = lambda k: (lambda v: v["perception_ms"][k])
hw_rows = "\n".join([
    rowv("People: whole frame", pm("people_whole_frame"), "{:.0f}"),
    rowv("People: 6 strips", pm("people_strips"), "{:.0f}"),
    rowv("Hands + MLP / person", pm("hands_per_person"), "{:.1f}"),
    rowv("Face + iris / person", pm("gaze_per_person"), "{:.1f}"),
    rowv(r"\textbf{Networks, frame}", lambda v: v["networks_ms"], "{:.0f}"),
    r"\midrule",
    r"\multicolumn{4}{@{}l}{\emph{After the networks (tracking, cues, decision)}}\\",
    "Gesture only & " + " & ".join("$<$0.01" if dv[c]["gesture_only_ms"] < 0.005 else f"{dv[c]['gesture_only_ms']:.2f}" for c in cols) + r"\\",
    rowv("Facing only", lambda v: v["facing_only_ms"], "{:.2f}"),
    rowv("Logistic regr.", lambda v: v["logreg_ms"], "{:.2f}"),
    rowv("Type-1 + gaze", lambda v: v["type1_ms"], "{:.2f}"),
    rowv(r"\textbf{IT2 + gaze (ours)}", lambda v: v["ours_ms"], "{:.2f}"),
    r"\midrule",
    rowv("Frames per second", lambda v: v["fps"], "{:.1f}"),
    rowv(r"Ours, \% of frame", lambda v: v["ours_share_pct"], "{:.1f}"),
])
gpu = " and ".join(("the desktop's " + g["gpu"].replace("NVIDIA GeForce ", "")) if g["device"] == "Desktop CPU"
                   else "the laptop's integrated graphics" for g in sorted(HW["gpu_delegate"], key=lambda g: g["device"] != "Desktop CPU"))
v0 = next(iter(dv.values()))["versions"]
by = TR["by_scenario"]
write("supp_cost", rf"""\begin{{table}}[h]
\centering\small\setlength{{\tabcolsep}}{{3pt}}
\caption{{Top: median time per frame (ms) with {next(iter(dv.values()))['people']:.0f} people in view on three devices,
same code, models, frames and library versions (Python {v0['python'][:4]}, MediaPipe {v0['mediapipe']}), one
process on the CPU: Raspberry Pi 5 (4 GB), laptop AMD Ryzen 7 5825U, desktop AMD Ryzen 9 9950X. Rows below the line time everything after the neural networks on their saved outputs.
MediaPipe's GPU mode failed to run on {gpu}. Bottom: track IDs per
person in view (tracks of $\ge$10 frames).}}
\label{{tab:supp_cost}}
\begin{{tabular}}{{@{{}}lrrr@{{}}}}
\toprule
& Raspberry & Laptop & Desktop\\
& Pi 5 & CPU & CPU\\
\midrule
""" + hw_rows + r"""
\bottomrule
\end{tabular}\\[6pt]
\begin{tabular}{@{}lcc@{}}
\toprule
Scen. & IDs/person & extra/min\\
\midrule
""" + "\n".join(f"{s} & {v['tracks_per_person']:.2f} & {v['extra_per_min']:.1f}\\\\" for s, v in by.items()) + r"""
\bottomrule
\end{tabular}
\end{table}
""")
print("wrote tables/supp_{scenario,stats,splits,untuned,annot,walking,cost}.tex")
